enum JpegSubsamplingType {
  kJpegYuv420,
  kJpegYuv422,
  kJpegYuv444,
  kJpegYuv400,
  kJpegUnknown
};

struct Buffer {
  const uint8_t* data;
  int len;
};

struct BufferVector {
  Buffer* buffers;
  int len;
  int pos;
};

class LIBYUV_API MJpegDecoder {
 public:
  typedef void (*CallbackFunction)(void* opaque,
                                   const uint8_t* const* data,
                                   const int* strides,
                                   int rows);

  static const int kColorSpaceUnknown;
  static const int kColorSpaceGrayscale;
  static const int kColorSpaceRgb;
  static const int kColorSpaceYCbCr;
  static const int kColorSpaceCMYK;
  static const int kColorSpaceYCCK;

  MJpegDecoder();
  ~MJpegDecoder();

  LIBYUV_BOOL LoadFrame(const uint8_t* src, size_t src_len);
  int GetWidth();
  int GetHeight();
  int GetColorSpace();
  int GetNumComponents();
  int GetHorizSampFactor(int component);
  int GetVertSampFactor(int component);
  int GetHorizSubSampFactor(int component);
  int GetVertSubSampFactor(int component);
  int GetImageScanlinesPerImcuRow();
  int GetComponentScanlinesPerImcuRow(int component);
  int GetComponentWidth(int component);
  int GetComponentHeight(int component);
  int GetComponentStride(int component);
  int GetComponentSize(int component);
  LIBYUV_BOOL UnloadFrame();
  LIBYUV_BOOL DecodeToBuffers(uint8_t** planes, int dst_width, int dst_height);
  LIBYUV_BOOL DecodeToCallback(CallbackFunction fn,
                               void* opaque,
                               int dst_width,
                               int dst_height);
  static JpegSubsamplingType JpegSubsamplingTypeHelper(
      int* subsample_x,
      int* subsample_y,
      int number_of_components);

 private:
  void AllocOutputBuffers(int num_outbufs);
  void DestroyOutputBuffers();
  LIBYUV_BOOL StartDecode();
  LIBYUV_BOOL FinishDecode();
  void SetScanlinePointers(uint8_t** data);
  LIBYUV_BOOL DecodeImcuRow();
  int GetComponentScanlinePadding(int component);

  Buffer buf_; 
  BufferVector buf_vec_;

  jpeg_decompress_struct* decompress_struct_;
  jpeg_source_mgr* source_mgr_;
  SetJmpErrorMgr* error_mgr_;

  LIBYUV_BOOL has_scanline_padding_;

  int num_outbufs_;
  uint8_t*** scanlines_;
  int* scanlines_sizes_;
  uint8_t** databuf_;
  int* databuf_strides_;
};

