import random
import struct
from typing import Tuple

# Generator for NV21 (Y + interleaved VU) images and related grayscale (I400) data.
# The fuzz stubs use FUZZ_PARAM_STR() as a repeating byte source to fill planes sized
# from computed strides and dimensions. We therefore return a compact bytestream that
# encodes: width/height ranges, stride deltas, and plane payloads that can tile when
# the stub repeats them. We include multiple image samples concatenated so different
# stubs see varied contents from the same FUZZ_PARAM_STR buffer.

# NV21 summary:
# - width, height: even
# - Y plane: height rows, src_stride_y >= width
# - VU plane: (height/2) rows, src_stride_vu >= width, bytes are interleaved V then U
# I400 summary:
# - only Y plane of size src_stride_y * height
# The stubs copy from FUZZ_PARAM_STR cyclically; we thus craft patterned payloads
# that include ramps, edge values, and chroma test patterns.

_MAX_BUF = 4096


def _even(n: int) -> int:
    return n & ~1


def _rand_even(r: random.Random, lo: int, hi: int) -> int:
    # inclusive bounds on even numbers
    if lo % 2:
        lo += 1
    if hi % 2:
        hi -= 1
    if lo > hi:
        lo, hi = 2, 64
    # choose even in [lo, hi]
    k = r.randrange((hi - lo) // 2 + 1)
    return lo + 2 * k


def _make_nv21_sample(r: random.Random, width: int, height: int,
                      y_stride_extra: int, vu_stride_extra: int) -> bytes:
    # Strides as in stubs: stride = width + delta, ensure >= width and even for chroma rows logically.
    src_stride_y = max(width, width + y_stride_extra)
    src_stride_vu = max(width, width + vu_stride_extra)

    # Build Y plane with mixed patterns: ramps, blocks, edges.
    y_rows = []
    for y in range(height):
        row = bytearray(src_stride_y)
        # Fill visible width with pattern; padding bytes also filled (not strictly required but fine)
        mode = ((y // 2) + (width // 2)) % 4
        if mode == 0:
            # Luma ramp across width
            for x in range(width):
                row[x] = (x * 255) // max(1, (width - 1))
        elif mode == 1:
            # Vertical step: alternate dark/bright rows
            val = 32 if (y % 4 < 2) else 224
            for x in range(width):
                row[x] = val
        elif mode == 2:
            # Center bright spot
            for x in range(width):
                dx = abs(x - width // 2)
                row[x] = 255 - min(255, dx * 8)
        else:
            # Checkerboard 8x8-ish via x^y
            for x in range(width):
                row[x] = 32 + (((x ^ y) & 7) * 28)
        # pad bytes: repeat last pixel
        if src_stride_y > width:
            pad_val = row[width - 1]
            for x in range(width, src_stride_y):
                row[x] = pad_val
        y_rows.append(bytes(row))

    # Build VU plane: interleaved V,U at full row width (same as Y stride in stubs)
    vu_rows = []
    for j in range(height // 2):
        row = bytearray(src_stride_vu)
        pattern = j % 5
        for x in range(0, width, 2):
            if pattern == 0:
                # Neutral chroma (gray)
                v, u = 128, 128
            elif pattern == 1:
                # Strong red-ish (high V)
                v, u = 200, 64
            elif pattern == 2:
                # Strong blue-ish (high U)
                v, u = 64, 200
            elif pattern == 3:
                # Alternating chroma stripes
                stripe = (x // 2) % 4
                if stripe < 2:
                    v, u = 180, 90
                else:
                    v, u = 90, 180
            else:
                # Ramp chroma across width
                v = (x * 255) // max(1, (width - 2))
                u = 255 - v
            # Write two luma positions share one VU pair in NV21 semantics; here we fill interleaved V,U
            row[x] = v
            if x + 1 < width:
                row[x + 1] = u
        # pad the rest with the last VU pair
        last_v = row[max(0, width - 2)] if width >= 2 else 128
        last_u = row[max(0, width - 1)] if width >= 1 else 128
        for x in range(width, src_stride_vu, 2):
            row[x] = last_v
            if x + 1 < src_stride_vu:
                row[x + 1] = last_u
        vu_rows.append(bytes(row))

    return b''.join(y_rows) + b''.join(vu_rows)


def _make_i400_sample(r: random.Random, width: int, height: int, y_stride_extra: int) -> bytes:
    src_stride_y = max(width, width + y_stride_extra)
    rows = []
    for y in range(height):
        row = bytearray(src_stride_y)
        # Horizontal gradient with noise sprinkles
        for x in range(width):
            base = (x * 255) // max(1, (width - 1))
            noise = (3 if (x ^ y) & 1 else 0) + (5 if (x * 7 + y * 13) % 29 == 0 else 0)
            v = max(0, min(255, base + noise))
            row[x] = v
        if src_stride_y > width:
            pad = row[width - 1]
            for x in range(width, src_stride_y):
                row[x] = pad
        rows.append(bytes(row))
    return b''.join(rows)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose a portfolio of small even sizes similar to the stubs (2..16/18/...) to keep under 4096 bytes
    samples: list[bytes] = []

    # Create 3 NV21 samples with varied strides and chroma patterns
    for _ in range(3):
        w = _rand_even(r, 2, 32)
        h = _rand_even(r, 2, 32)
        # stride extras mimic fuzz stub deltas (0..7)
        y_extra = r.randrange(0, 8)
        vu_extra = r.randrange(0, 8)
        samples.append(_make_nv21_sample(r, w, h, y_extra, vu_extra))

    # Create 2 grayscale (I400) samples for I400ToNV21 path
    for _ in range(2):
        w = _rand_even(r, 2, 32)
        h = _rand_even(r, 2, 32)
        y_extra = r.randrange(0, 8)
        samples.append(_make_i400_sample(r, w, h, y_extra))

    # Add compact calibration blocks with explicit byte sets to enrich repeating FUZZ_PARAM_STR patterns
    def block(pattern_id: int, ln: int) -> bytes:
        if pattern_id == 0:
            return bytes(range(ln))
        if pattern_id == 1:
            return bytes([0, 255] * (ln // 2)) + (b"" if ln % 2 == 0 else b"\x80")
        if pattern_id == 2:
            return b"YUV!NV21" * (ln // 8) + bytes([ln % 256]) * (ln % 8)
        # default random block with stable seed
        return bytes(r.getrandbits(8) for _ in range(ln))

    samples.append(block(0, 64))
    samples.append(block(1, 64))
    samples.append(block(2, 64))

    # Concatenate, trim to max size
    out = b"".join(samples)
    if len(out) > _MAX_BUF:
        out = out[:_MAX_BUF]

    # Ensure non-empty
    if not out:
        out = b"\x80" * 16

    return out

import random
from typing import List

def _prng(seed: int) -> random.Random:
    return random.Random(seed & 0xFFFFFFFF)

# Build small valid grayscale (I400/J400) and RGB/RAW buffers because stubs
# copy the FUZZ_PARAM_STR cyclically into required plane buffers.
# We return a concatenation of several crafted patterns so that cycling
# through r[i % r.size()] exercises different luminance/alpha/edge cases.

def _make_gradient(width: int, height: int, stride: int) -> bytes:
    # Horizontal ramp 0..255, repeated per row; pad to stride
    rows: List[bytes] = []
    for y in range(height):
        row = bytes(((x * 255) // max(1, width - 1) for x in range(width)))
        if stride > width:
            row += bytes([row[-1]]) * (stride - width)
        rows.append(row)
    return b"".join(rows)

def _make_checker(width: int, height: int, stride: int, a: int = 32, b: int = 224) -> bytes:
    rows: List[bytes] = []
    for y in range(height):
        row = bytearray()
        for x in range(width):
            row.append(a if ((x // 2) ^ (y // 2)) & 1 else b)
        if stride > width:
            row.extend([row[-1]] * (stride - width))
        rows.append(bytes(row))
    return b"".join(rows)

def _make_saw(width: int, height: int, stride: int, phase: int) -> bytes:
    rows: List[bytes] = []
    for y in range(height):
        row = bytearray()
        for x in range(width):
            row.append(((x + y + phase) % 256))
        if stride > width:
            row.extend([row[-1]] * (stride - width))
        rows.append(bytes(row))
    return b"".join(rows)

def _make_rgb24(width: int, height: int, stride: int, pattern: str) -> bytes:
    # stride is bytes per row (>= width*3), pack RGB in 24bpp
    rows: List[bytes] = []
    for y in range(height):
        row = bytearray()
        for x in range(width):
            if pattern == 'gray':
                v = (x * 255) // max(1, width - 1)
                row += bytes((v, v, v))
            elif pattern == 'colorbars':
                band = (x * 7) // max(1, width)
                colors = [(255,255,255),(255,255,0),(0,255,255),(0,255,0),(255,0,255),(255,0,0),(0,0,255)]
                r,g,b = colors[band]
                row += bytes((r,g,b))
            else:  # 'saw'
                row += bytes(((x+y) % 256, (2*x+y) % 256, (3*x+y) % 256))
        if stride > width*3:
            row.extend([row[-1]] * (stride - width*3))
        rows.append(bytes(row))
    return b"".join(rows)

def _mix(parts: List[bytes], max_len: int, rng: random.Random) -> bytes:
    rng.shuffle(parts)
    out = b""
    for p in parts:
        if len(out) + len(p) > max_len:
            # truncate last part to fit
            out += p[: max(0, max_len - len(out))]
            break
        out += p
    return out

def generate(seed: int) -> bytes:
    rng = _prng(seed)
    # Choose small dimensions that the stubs commonly pick; include even widths for 4:2:0 paths
    w_y = rng.choice([2, 4, 8, 13, 16, 22])
    h_y = rng.choice([2, 4, 7, 12, 18, 22])
    stride_y = w_y + rng.randrange(0, 8)
    if stride_y < w_y:
        stride_y = w_y

    # For NV21/I420 chroma-related stubs, they only use FUZZ_PARAM_STR for Y, U, V, alpha sources separately.
    # Our buffer will be cycled into those, so include variants representative of U/V constant 128 and extremes.

    y_grad = _make_gradient(w_y, h_y, stride_y)
    y_chk = _make_checker(w_y, h_y, stride_y, 16, 235)  # video-range extremes for J400/I400 conversions
    y_saw = _make_saw(w_y, h_y, stride_y, phase=rng.randrange(0, 256))

    # Build an alpha plane-like buffer (used by BlendPlane/I420Blend). Full-width stripes 0..255.
    a_w = w_y
    a_h = h_y
    a_stride = a_w + rng.randrange(0, 8)
    if a_stride < a_w:
        a_stride = a_w
    alpha = _make_gradient(a_w, a_h, a_stride)

    # RGB24/RAW sources for RGB24ToJ400/RAWToJ400
    w_rgb = rng.choice([3, 6, 9, 12, 15, 18, 21])
    h_rgb = rng.choice([2, 5, 8, 11, 14, 17])
    stride_rgb = (w_rgb * 3) + (rng.randrange(0, 12) & ~1)  # even stride as in stub
    if stride_rgb < w_rgb * 3:
        stride_rgb = w_rgb * 3
    rgb_gray = _make_rgb24(w_rgb, h_rgb, stride_rgb, 'gray')
    rgb_bars = _make_rgb24(w_rgb, h_rgb, stride_rgb, 'colorbars')

    # Include constants useful for chroma-neutral fill when cycled into U/V by stubs
    neutral_uv = bytes([128]) * rng.randrange(64, 256)
    black = bytes([0]) * rng.randrange(64, 256)
    white = bytes([255]) * rng.randrange(64, 256)

    parts = [y_grad, y_chk, y_saw, alpha, rgb_gray, rgb_bars, neutral_uv, black, white]

    # Limit total to 4096 bytes
    return _mix(parts, 4096, rng)

import random
from typing import List

# Generator for interleaved UV bytes (8-bit): repeating [U,V] tuples.
# Targets functions operating on UV rows/planes and expecting valid sizes.
# Strategy:
# - Produce a UV plane or two UV rows with reasonable stride padding.
# - Include patterns that exercise edges: solid colors, gradients, checkerboards,
#   extreme values, and randomized content.
# - Keep total size <= 2048 bytes as per fuzz stubs.

MAX_BYTES = 2048
BPP = 2  # bytes per interleaved UV pixel


def _pack_rows(rows: List[bytes]) -> bytes:
    return b"".join(rows)


def _uv_tuple(u: int, v: int) -> bytes:
    return bytes((u & 0xFF, v & 0xFF))


def _make_uv_row(width_uv: int, pattern: str, seed: int, u0: int = 0, v0: int = 0) -> bytes:
    rng = random.Random(seed)
    row = bytearray(width_uv * BPP)
    if pattern == "solid":
        u, v = u0 & 0xFF, v0 & 0xFF
        for i in range(width_uv):
            row[2*i] = u
            row[2*i+1] = v
    elif pattern == "checker":
        for i in range(width_uv):
            if (i & 1) == 0:
                row[2*i] = 16
                row[2*i+1] = 128
            else:
                row[2*i] = 240
                row[2*i+1] = 128
    elif pattern == "gradient":
        for i in range(width_uv):
            # Horizontal gradients for U and V
            u = (i * 255) // max(1, width_uv - 1)
            v = 255 - u
            row[2*i] = u
            row[2*i+1] = v
    elif pattern == "edges":
        # Alternating min/max
        for i in range(width_uv):
            row[2*i] = 0 if (i & 1) == 0 else 255
            row[2*i+1] = 255 if (i & 1) == 0 else 0
    elif pattern == "random":
        for i in range(width_uv):
            row[2*i] = rng.randrange(256)
            row[2*i+1] = rng.randrange(256)
    else:
        # default random
        for i in range(width_uv):
            row[2*i] = rng.randrange(256)
            row[2*i+1] = rng.randrange(256)
    return bytes(row)


def _two_row_box_input(dst_width: int, add_pad: int, pattern_a: str, pattern_b: str, seed: int) -> bytes:
    # For ScaleUVRowDown2Box* stubs: they require two source rows with stride >= (dst_width+1)*2 or similar.
    # We'll build src_stride as (dst_width + add_pad) * BPP and then two rows fitting exactly into that stride.
    width_uv = max(1, dst_width + add_pad)
    src_stride = width_uv * BPP
    # Ensure total size <= MAX_BYTES
    if src_stride * 2 > MAX_BYTES:
        width_uv = max(1, (MAX_BYTES // 2) // BPP)
        src_stride = width_uv * BPP
    row0 = _make_uv_row(width_uv, pattern_a, seed ^ 0xA5)
    row1 = _make_uv_row(width_uv, pattern_b, seed ^ 0x5A)
    return _pack_rows([row0, row1])


def _up2_linear_input(dst_width: int, pattern: str, seed: int) -> bytes:
    # For ScaleUVRowUp2_Linear*: needs ceil(dst_width/2) UV pixels
    src_len_uv = (dst_width + 1) // 2
    row = _make_uv_row(src_len_uv, pattern, seed)
    return row


def _up2_bilinear_input(dst_width: int, pattern_top: str, pattern_bottom: str, pad_factor: int, seed: int) -> bytes:
    # For ScaleUVRowUp2_Bilinear*: two source rows, second begins at src_stride.
    src_len_uv = (dst_width + 1) // 2
    base_width = src_len_uv + pad_factor
    if base_width < src_len_uv:
        base_width = src_len_uv
    src_stride = base_width * BPP
    # Total must be <= MAX_BYTES
    total = src_len_uv * BPP + src_stride
    if total > MAX_BYTES:
        # shrink base_width as needed
        max_stride = MAX_BYTES - (src_len_uv * BPP)
        base_width = max(1, max_stride // BPP)
        src_stride = base_width * BPP
    row0 = _make_uv_row(src_len_uv, pattern_top, seed ^ 0x1111)
    # row1 will occupy full src_stride; we fill prefix with data and pad with zeros if needed
    row1_content = _make_uv_row(src_len_uv, pattern_bottom, seed ^ 0x2222)
    if len(row1_content) < src_stride:
        row1 = row1_content + b"\x00" * (src_stride - len(row1_content))
    else:
        row1 = row1_content[:src_stride]
    return row0 + row1


def _uvscale_plane(src_w: int, src_h: int, dst_w: int, dst_h: int, src_pad: int, pattern: str, seed: int) -> bytes:
    # Build a full plane for UVScale
    src_stride = src_w * BPP + src_pad
    # Enforce limits
    if src_stride <= 0:
        src_stride = src_w * BPP
    while src_stride * src_h > MAX_BYTES and src_h > 1:
        src_h -= 1
    src_h = max(1, src_h)
    src_stride = min(src_stride, MAX_BYTES)  # not strictly necessary, just in case
    # Create plane line by line to include padding
    rng = random.Random(seed)
    rows = []
    for y in range(src_h):
        content = _make_uv_row(src_w, pattern, seed ^ (y * 0x9E3779B1))
        if len(content) < src_stride:
            pad = bytes(rng.randrange(256) for _ in range(src_stride - len(content)))
            rows.append(content + pad)
        else:
            rows.append(content[:src_stride])
    return _pack_rows(rows)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a target-style scenario to cover various stubs.
    scenario = rng.randrange(6)

    # Common width choices favor small and SIMD-friendly sizes
    width_choices = [1, 2, 3, 4, 7, 8, 15, 16, 17, 31, 32, 63]
    pattern_choices = ["solid", "checker", "gradient", "edges", "random"]

    if scenario == 0:
        # Two-row input for 2x2 box downscale
        dst_w = rng.choice(width_choices)
        add_pad = rng.randrange(0, 4)  # small padding to vary stride
        pa = rng.choice(pattern_choices)
        pb = rng.choice(pattern_choices)
        return _two_row_box_input(dst_w, add_pad, pa, pb, seed)

    if scenario == 1:
        # Up2 linear: single row, ceil(dst/2)
        dst_w = rng.choice(width_choices)
        pat = rng.choice(pattern_choices)
        return _up2_linear_input(dst_w, pat, seed)

    if scenario == 2:
        # Up2 bilinear: two rows with stride padding
        dst_w = rng.choice(width_choices)
        pad_factor = rng.randrange(0, 4)
        pt = rng.choice(pattern_choices)
        pb = rng.choice(pattern_choices)
        return _up2_bilinear_input(dst_w, pt, pb, pad_factor, seed)

    if scenario == 3:
        # Plane for UVScale: moderate sizes with padding and structured content
        src_w = rng.choice(width_choices)
        src_h = rng.choice([1, 2, 3, 4, 8, 15, 16, 31])
        dst_w = rng.choice(width_choices)  # not used directly, but influences intent
        dst_h = rng.choice([1, 2, 3, 4, 8, 15, 16, 31])
        pad = rng.randrange(0, BPP * 3)
        pat = rng.choice(pattern_choices)
        return _uvscale_plane(src_w, src_h, dst_w, dst_h, pad, pat, seed)

    if scenario == 4:
        # Stress: maximum within cap for two-row box with large stride
        dst_w = rng.choice([31, 32, 63])
        add_pad = 3
        return _two_row_box_input(dst_w, add_pad, "gradient", "edges", seed)

    # scenario == 5
    # Edge: narrow widths, extreme values, ensure valid yet tiny buffers
    dst_w = rng.choice([1, 2, 3, 4])
    choice = rng.randrange(3)
    if choice == 0:
        return _two_row_box_input(dst_w, 0, "solid", "solid", seed)
    elif choice == 1:
        return _up2_linear_input(dst_w, "edges", seed)
    else:
        return _up2_bilinear_input(dst_w, "checker", "checker", 0, seed)
